"""Generate docs/detection_rules.md from the rule catalog (single source of truth)."""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from agent.rules_data import (BLACKLISTED_PROCESSES, COMMAND_LINE_PATTERNS, CRITICAL_PROCESSES,  # noqa: E402
                              RULE_CATALOG, SUSPICIOUS_PARENT_CHILD)


def main():
    out = ["# Detection Rules", "",
           "> Generated by `python tools/gen_rule_docs.py` from `agent/rules_data.py` - do not edit by hand.", "",
           f"The agent ships **{len(RULE_CATALOG)} rules**, each mapped to a MITRE ATT&CK technique.", "",
           "## Severity model", "",
           "| Score | Severity | Meaning |", "|---|---|---|",
           "| 9-10 | CRITICAL | Near-certain malicious behaviour or multiple independent indicators |",
           "| 6-8 | HIGH | Strong indicator that needs prompt investigation |",
           "| 3-5 | MEDIUM | Unusual - investigate when time allows |",
           "| 1-2 | LOW | Informational / weak signal |", "",
           "Independent rules that fire for the same process, service or startup item are combined by "
           "**CORR-001**, which raises the severity (e.g. unsigned + staging directory + double extension).", "",
           "## Rule catalog", "",
           "| ID | Rule | Category | Tactic | Technique |", "|---|---|---|---|---|"]
    for rid, m in RULE_CATALOG.items():
        out.append(f"| {rid} | {m['name']} | {m['alert_type']} | {m['tactic']} | {m['technique']} {m['technique_name']} |")
    out += ["", "## Rule details", ""]
    for rid, m in RULE_CATALOG.items():
        out += [f"### {rid} - {m['name']}", "", m["description"], "",
                f"- **MITRE ATT&CK:** {m['technique']} - {m['technique_name']} ({m['tactic']})",
                f"- **Response:** {m['recommendation']}", ""]
    out += ["## Parent -> child relationships monitored (PROC-001)", "",
            "| Parent | Suspicious children | Score | Technique |", "|---|---|---|---|"]
    for parent, children in sorted(SUSPICIOUS_PARENT_CHILD.items()):
        score, technique, _ = next(iter(children.values()))
        out.append(f"| `{parent}` | {', '.join(f'`{c}`' for c in sorted(children))} | {score} | {technique} |")
    out += ["", "## Critical Windows processes - expected location and parent (PROC-005 / PROC-007)", "",
            "| Process | Expected directory | Legitimate parent(s) |", "|---|---|---|"]
    for name, spec in CRITICAL_PROCESSES.items():
        out.append(f"| `{name}` | `{sorted(spec['dirs'])[0]}` | {', '.join(f'`{p}`' for p in sorted(spec['parents']))} |")
    out += ["", "## Command-line patterns (PROC-008, SVC-007, PERS-002/004)", "",
            "| Pattern | Score | Technique |", "|---|---|---|"]
    for label, _, score, technique in COMMAND_LINE_PATTERNS:
        out.append(f"| {label} | {score} | {technique} |")
    out += ["", f"## Blacklist ({len(BLACKLISTED_PROCESSES)} tools)", "",
            "| Name | Category | Score |", "|---|---|---|"]
    for name, (category, score) in sorted(BLACKLISTED_PROCESSES.items()):
        out.append(f"| `{name}` | {category} | {score} |")
    out += ["", "## Tuning", "",
            "Edit `config/custom_rules.json` to add approved software (`allowed_processes`), extra blacklist entries, "
            "trusted service names and suppressions. Add known-bad hashes to `config/ioc_hashes.txt`.", ""]
    target = ROOT / "docs" / "detection_rules.md"
    target.write_text("\n".join(out), encoding="utf-8")
    print(f"wrote {target.relative_to(ROOT)} ({len(RULE_CATALOG)} rules)")


if __name__ == "__main__":
    main()
